INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist DQL nur für Datenabfragen zuständig?', 2, '[{"text": "Ja", "correct": true, "because": "Fokus auf Datenabruf"}, {"text": "Nein", "correct": false, "because": "Hauptzweck ist Abfragen"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Nutzung von DQL?', 3, '[{"text": "Genauigkeit", "correct": true, "because": "Sichert richtige Ergebnisse"}, {"text": "Schnelle Syntax", "correct": false, "because": "Präzision wichtiger"}, {"text": "Minimale Zeilen", "correct": false, "because": "Funktion zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Befehle gehören zu DQL?', 5, '[{"text": "SELECT", "correct": true, "because": "Ruft Daten ab"}, {"text": "FROM", "correct": true, "because": "Definiert Quelle"}, {"text": "INSERT", "correct": false, "because": "DML-Befehl"}, {"text": "CREATE", "correct": false, "because": "DDL-Befehl"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) SELECT fragt Daten ab. b) DQL ändert Daten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "DQL manipuliert nicht"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Arbeit mit DQL?', 4, '[{"text": "WHERE-Bedingung", "correct": false, "because": "Filtert Ergebnisse"}, {"text": "Tabellenstruktur", "correct": false, "because": "Basis der Abfrage"}, {"text": "Farbanpassung", "correct": true, "because": "Kein technischer Nutzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob DML auch Daten abfragen kann?', 2, '[{"text": "Nein", "correct": true, "because": "DQL ist für Abfragen"}, {"text": "Ja", "correct": false, "because": "DML manipuliert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Befehl wähle ich, um Daten aus einer Tabelle abzurufen?', 3, '[{"text": "SELECT", "correct": true, "because": "Kernbefehl für Abfragen"}, {"text": "UPDATE", "correct": false, "because": "DML-Befehl"}, {"text": "ALTER", "correct": false, "because": "DDL-Befehl"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bringen mir DQL-Befehle?', 5, '[{"text": "Datenanalyse", "correct": true, "because": "Ermöglicht Einblicke"}, {"text": "Flexibilität", "correct": true, "because": "Filter und Sortierung"}, {"text": "Datenänderung", "correct": false, "because": "Nicht DQL-Zweck"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) WHERE filtert Daten. b) DQL definiert Tabellen. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Tabellen sind DDL"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für DQL?', 4, '[{"text": "Tabellen", "correct": false, "because": "Quelle der Abfrage"}, {"text": "Spalten", "correct": false, "because": "Definiert Ausgabe"}, {"text": "Spielemodus", "correct": true, "because": "Kein Datenbankzweck"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann SELECT auch Daten ändern?', 2, '[{"text": "Nein", "correct": true, "because": "Nur Abfrage, keine Änderung"}, {"text": "Ja", "correct": false, "because": "DML-Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen DQL effektiv?', 4, '[{"text": "Präzise Filter", "correct": true, "because": "Genauere Ergebnisse"}, {"text": "Optimierte Joins", "correct": true, "because": "Verknüpfung effizient"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Hardwareaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass DQL Daten löschen kann. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Löschen ist DML"}, {"text": "Ja", "correct": false, "because": "Falsche Zuordnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei DQL-Anweisungen?', 3, '[{"text": "Relevanz der Daten", "correct": true, "because": "Sichert nützliche Ergebnisse"}, {"text": "Minimale Spalten", "correct": false, "because": "Flexibilität wichtiger"}, {"text": "Schnelle Syntax", "correct": false, "because": "Korrektheit zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) ORDER BY sortiert Daten. b) DQL fügt Daten hinzu.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Hinzufügen ist DML"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Optionen verbessern DQL?', 5, '[{"text": "JOIN-Klauseln", "correct": true, "because": "Verknüpfen Tabellen"}, {"text": "GROUP BY", "correct": true, "because": "Aggregiert Daten"}, {"text": "Datenlöschung", "correct": false, "because": "Nicht DQL"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei DQL unwichtig?', 3, '[{"text": "Abfrageziel", "correct": false, "because": "Kern der Abfrage"}, {"text": "Filterbedingungen", "correct": false, "because": "Steuern Ergebnisse"}, {"text": "Oberflächen-Design", "correct": true, "because": "Kein technischer Nutzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann SELECT mehrere Tabellen abfragen?', 3, '[{"text": "Ja", "correct": true, "because": "Mit Joins möglich"}, {"text": "Nein", "correct": false, "because": "Häufige Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob DQL auch Datenintegrität sichert?', 2, '[{"text": "Nein", "correct": true, "because": "Nur Abfrage, keine Prüfung"}, {"text": "Ja", "correct": false, "because": "Constraints sichern"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Befehl wähle ich, um Daten zu sortieren?', 4, '[{"text": "ORDER BY", "correct": true, "because": "Sortiert Abfrageergebnisse"}, {"text": "WHERE", "correct": false, "because": "Filtert nur"}, {"text": "INSERT", "correct": false, "because": "DML-Befehl"}]');
